import { Box, Button, Link, Popover, Stack, Typography } from '@mui/material'
import QRCode from 'qrcode'
import { useEffect, useMemo, useState } from 'react'
import type { RemoteControlStatus } from '../../data/electron_remote_control_bridge'
import { connectUrlFromEndpoint } from '../../data/remote_connect_string'
import { copyTextToClipboard } from '../../services/clipboard_text'

interface RemoteControlConnectionInfoProps {
    anchorEl: HTMLElement | null
    onClose: () => void
    open: boolean
    status: RemoteControlStatus
}

interface ConnectTarget {
    connectUrl: string
    endpoint: string
    label: string
}

/**
 * Connect targets to share, IP first: `.local` mDNS resolves unreliably on Android, so a raw LAN IP is
 * the dependable default.
 */
function connectTargets(status: RemoteControlStatus): ConnectTarget[] {
    const targets: ConnectTarget[] = []
    for (const ip of status.ipEndpoints ?? []) {
        const connectUrl = connectUrlFromEndpoint(ip)
        if (connectUrl) targets.push({ connectUrl, endpoint: ip, label: 'IP address' })
    }
    if (status.hostnameEndpoint) {
        const connectUrl = connectUrlFromEndpoint(status.hostnameEndpoint)
        if (connectUrl) targets.push({ connectUrl, endpoint: status.hostnameEndpoint, label: 'Hostname' })
    }

    return targets
}

/** Popover shown from the Serve button: hostname/IP connect links, a copy button and a QR of the selected link. */
export function RemoteControlConnectionInfo(props: RemoteControlConnectionInfoProps) {
    const { anchorEl, onClose, open, status } = props
    const targets = useMemo(() => connectTargets(status), [status])
    const [selectedUrl, setSelectedUrl] = useState<string | null>(null)
    const [qrCode, setQrCode] = useState<{ connectUrl: string, dataUrl: string } | null>(null)
    const [copiedUrl, setCopiedUrl] = useState<string | null>(null)

    // Default the QR/copy target to the first (IP) entry; re-pin if the endpoint set changes.
    const activeUrl = targets.some((target) => target.connectUrl === selectedUrl)
        ? selectedUrl
        : (targets[0]?.connectUrl ?? null)
    const qrDataUrl = qrCode?.connectUrl === activeUrl ? qrCode.dataUrl : null
    const copied = copiedUrl === activeUrl

    useEffect(() => {
        if (!activeUrl) return undefined

        let active = true
        void QRCode.toDataURL(activeUrl, { margin: 1, width: 176 }).then(
            (url) => {
                if (active) setQrCode({ connectUrl: activeUrl, dataUrl: url })
            },
            () => {
                if (active) setQrCode(null)
            },
        )

        return () => {
            active = false
        }
    }, [activeUrl])

    const handleCopy = async () => {
        if (!activeUrl) return
        try {
            await copyTextToClipboard(activeUrl)
        } catch {
            // The connect-URL button has always ignored copy failures; keep it dialog-free.
        }
        setCopiedUrl(activeUrl)
    }

    const handleCopyClick = () => void handleCopy()

    return (
        <Popover
            anchorEl={anchorEl}
            anchorOrigin={{ horizontal: 'left', vertical: 'bottom' }}
            onClose={onClose}
            open={open}
        >
            <Stack spacing={1.5} sx={{ maxWidth: 280, p: 2 }}>
                {targets.length > 0 ? (
                    <Box>
                        <Typography variant="overline">Open on your phone</Typography>
                        <Typography color="text.secondary" variant="caption">
                            IP is most reliable; hostname (.local) may not resolve on Android.
                        </Typography>
                        <Stack spacing={0.5} sx={{ mt: 0.5 }}>
                            {targets.map((target) => (
                                <Link
                                    key={target.connectUrl}
                                    component="button"
                                    onClick={() => setSelectedUrl(target.connectUrl)}
                                    sx={{
                                        fontWeight: target.connectUrl === activeUrl ? 600 : 400,
                                        textAlign: 'left',
                                        wordBreak: 'break-all',
                                    }}
                                    type="button"
                                    variant="body2"
                                >
                                    {target.connectUrl}
                                </Link>
                            ))}
                        </Stack>
                    </Box>
                ) : (
                    <Typography variant="body2">â€”</Typography>
                )}
                {qrDataUrl ? (
                    <Box sx={{ display: 'flex', justifyContent: 'center' }}>
                        <img alt="Remote-control connect QR code" src={qrDataUrl} style={{ maxWidth: '100%' }} />
                    </Box>
                ) : null}
                <Button disabled={!activeUrl} onClick={handleCopyClick} size="small" variant="outlined">
                    {copied ? 'Copied' : 'Copy connect link'}
                </Button>
            </Stack>
        </Popover>
    )
}

const crypto = require('node:crypto');
const fs = require('node:fs');
const http = require('node:http');
const os = require('node:os');
const path = require('node:path');
const { WebSocketServer } = require('ws');
const { BRIDGE_ERROR_ENVELOPE_KEY, serializeBridgeError } = require('../../../shared/bridge_errors.mjs');

const DEFAULT_HOST = '127.0.0.1';
const DEFAULT_PORT = 0;
const SOCKET_OPEN_STATE = 1;
const REMOTE_CONTROL_STOP_CODE = 1001;
const NOT_FOUND_STATUS = 404;
const AGENT_EVENT_METHODS = new Set(['runSearchRegexpAgent']);
const STATIC_INDEX_FILE = 'index.html';
const CONTENT_TYPES = {
    '.css': 'text/css; charset=utf-8',
    '.html': 'text/html; charset=utf-8',
    '.ico': 'image/x-icon',
    '.js': 'text/javascript; charset=utf-8',
    '.json': 'application/json; charset=utf-8',
    '.png': 'image/png',
    '.svg': 'image/svg+xml',
    '.woff2': 'font/woff2',
};

function contentTypeFor(filePath) {
    return CONTENT_TYPES[path.extname(filePath).toLowerCase()] ?? 'application/octet-stream';
}

/** Maps a request URL path to an absolute file inside staticDir, or null when it escapes the root. */
function resolveStaticFile(staticDir, urlPath) {
    let pathname;
    try {
        pathname = decodeURIComponent(new URL(urlPath, 'http://localhost').pathname);
    } catch {
        return null;
    }
    if (pathname === '/' || pathname === '') pathname = `/${STATIC_INDEX_FILE}`;

    const resolved = path.resolve(staticDir, `.${pathname}`);
    const root = path.resolve(staticDir);
    if (resolved !== root && !resolved.startsWith(root + path.sep)) return null;

    return resolved;
}

function createInactiveState() {
    return {
        active: false,
        clientCount: 0,
        endpoint: null,
        hostnameEndpoint: null,
        ipEndpoints: [],
    };
}

function isLoopbackHost(host) {
    return host === '127.0.0.1' || host === 'localhost' || host === '::1';
}

// Virtual adapters (Hyper-V/WSL/VM bridges) report LAN-looking IPv4s that a phone on the real Wi-Fi
// cannot reach â€” Node does not flag them `internal`, so they slip past the loopback check. Exclude them
// so the fallback list only shows addresses a remote device can actually connect to.
const VIRTUAL_ADAPTER_PATTERN = /vethernet|virtualbox|vmware|hyper-v|\bwsl\b|loopback|\btap\b|npcap|bluetooth/iu;

/**
 * LAN-reachable IPv4 addresses, skipping internal (loopback), link-local (169.254.x) and virtual
 * (Hyper-V/WSL/VM) interfaces so only phone-reachable physical-adapter addresses are surfaced.
 */
function lanIpv4Addresses() {
    const addresses = [];
    for (const [name, entries] of Object.entries(os.networkInterfaces())) {
        if (VIRTUAL_ADAPTER_PATTERN.test(name)) continue;
        for (const entry of entries ?? []) {
            if (entry.family !== 'IPv4' || entry.internal) continue;
            if (entry.address.startsWith('169.254.')) continue;
            addresses.push(entry.address);
        }
    }

    return addresses;
}

function sendJson(socket, message) {
    if (socket.readyState !== SOCKET_OPEN_STATE) return;

    socket.send(JSON.stringify(message));
}

function errorMessage(error) {
    return error instanceof Error ? error.message : 'Remote-control request failed';
}

/**
 * Build the error part of a response. Marker properties such as `code` and `workingFolder` are
 * carried explicitly, because a message alone leaves the client unable to recognise recoverable
 * conditions like a missing working folder.
