const { spawn } = require('node:child_process');
const { assertGitRoot, requireRootPath } = require('../../git/git_commands');
const { terminateProcessTree } = require('../process_tree');
const { ActionCancellationError } = require('./action_cancellation_error');
const { resolvePlaceholders } = require('./action_text');

async function runCommand(project, command, signal, onOutput, spawnCommand = spawn) {
    const rootPath = requireRootPath(project);
    await assertGitRoot(rootPath);
    if (signal.aborted) throw new ActionCancellationError('Action cancelled');

    return new Promise((resolve, reject) => {
        const child = spawnCommand(command, { cwd: rootPath, shell: true, signal });
        let stderr = '';
        let stdout = '';
        child.stdout.on('data', (chunk) => {
            const output = chunk.toString();
            stdout += output;
            onOutput({ stderr: '', stdout: output });
        });
        child.stderr.on('data', (chunk) => {
            const output = chunk.toString();
            stderr += output;
            onOutput({ stderr: output, stdout: '' });
        });
        child.on('error', (error) => {
            if (signal.aborted) reject(new ActionCancellationError('Action cancelled'));
            else reject(error);
        });
        child.on('close', (exitCode) => {
            if (signal.aborted) {
                reject(new ActionCancellationError('Action cancelled'));
                return;
            }

            resolve({ command, exitCode: exitCode ?? 1, stderr, stdout });
        });
    });
}

async function waitForVisibleCommand(child, signal, terminate = terminateProcessTree) {
    return new Promise((resolve, reject) => {
        const handleAbort = () => {
            void terminate(child).catch(() => undefined);
        };
        signal.addEventListener('abort', handleAbort, { once: true });
        if (signal.aborted) handleAbort();
        child.on('error', (error) => {
            signal.removeEventListener('abort', handleAbort);
            if (signal.aborted) reject(new ActionCancellationError('Action cancelled'));
            else reject(error);
        });
        child.on('close', (exitCode) => {
            signal.removeEventListener('abort', handleAbort);
            if (signal.aborted) reject(new ActionCancellationError('Action cancelled'));
            else resolve(exitCode ?? 1);
        });
    });
}

/** Opens a separate Windows command window and resolves only after that window closes. */
async function runCommandInWindow(project, command, signal, _onOutput, dependencies = {}) {
    const rootPath = requireRootPath(project);
    await assertGitRoot(rootPath);
    if (signal.aborted) throw new ActionCancellationError('Action cancelled');

    const spawnCommand = dependencies.spawnCommand ?? spawn;
    const terminate = dependencies.terminateProcessTree ?? terminateProcessTree;
    const child = spawnCommand(command, {
        cwd: rootPath,
        detached: true,
        shell: true,
        stdio: 'inherit',
        windowsHide: false,
    });
    const exitCode = await waitForVisibleCommand(child, signal, terminate);

    return { command, exitCode, stderr: '', stdout: '' };
}

function executeCommandAction(input) {
    const command = resolvePlaceholders(
        input.command,
        input.context,
        input.project,
        input.primaryProject,
        input.projectFolder,
        input.releasesFolder,
        input.activeCardsFolder,
        '',
        input.diagramFile,
        input.version,
    );
    const onOutput = ({ stderr, stdout }) => input.onOutput({ command, stderr, stdout });

    const commandRunner = input.action.showCommandWindow ? input.commandWindowRunner : input.commandRunner;

    return commandRunner(input.project, command, input.signal, onOutput);
}

module.exports = { executeCommandAction, runCommand, runCommandInWindow };

const path = require('node:path');
const { requireRootPath } = require('../../git/git_commands');

const PLACEHOLDER_NAMES = [
    'active-cards-folder', 'worktree-folder', 'repository-folder', 'project-folder',
    'releases-folder', 'card-file', 'this-card', 'card-title', 'card-prompt',
    'conflict-file', 'conflict-files', 'diagram-changes', 'diagram-file', 'parent-node', 'version',
].join('|');
const PLACEHOLDER_PATTERN = new RegExp(`\\{\\{\\s*(${PLACEHOLDER_NAMES})\\s*\\}\\}`, 'gu');
const CARD_PROMPT_PLACEHOLDER_PATTERN = /\{\{\s*card-prompt\s*\}\}/u;

function resolvePlaceholders(
    text,
    context,
    runProject,
    primaryProject,
    projectFolder,
    releasesFolder,
    activeCardsFolder,
    extraPrompt,
    diagramFile,
    version,
) {
    return text.replace(PLACEHOLDER_PATTERN, (_match, name) => {
        if (name === 'version') {
            if (typeof version !== 'string' || version.trim().length === 0) throw new Error('Cannot resolve version placeholder without a version');

            return version;
        }
        if (name === 'active-cards-folder') {
            if (typeof activeCardsFolder !== 'string' || activeCardsFolder.length === 0) {
                throw new Error('Cannot resolve active-cards-folder placeholder without a configured working folder');
            }

            return path.resolve(requireRootPath(primaryProject), activeCardsFolder);
        }
        if (name === 'worktree-folder') return requireRootPath(runProject);
        if (name === 'repository-folder') return requireRootPath(primaryProject);
        if (name === 'project-folder') {
            if (typeof projectFolder !== 'string') {
                throw new Error('Cannot resolve project-folder placeholder without a configured project folder');
            }

            const repositoryFolder = requireRootPath(primaryProject);

            return projectFolder.length === 0 ? repositoryFolder : path.resolve(repositoryFolder, projectFolder);
        }
        if (name === 'releases-folder') {
            if (typeof releasesFolder !== 'string' || releasesFolder.length === 0) {
                throw new Error('Cannot resolve releases-folder placeholder without a configured releases folder');
            }

            return path.resolve(requireRootPath(primaryProject), releasesFolder);
        }
        if (name === 'card-prompt') return extraPrompt;
        if (name === 'diagram-changes') {
            if (context.kind !== 'diagram') throw new Error('Cannot resolve diagram-changes placeholder outside diagram context');
            if (!context.diagramId) throw new Error('Cannot resolve diagram-changes placeholder without an active diagram ID');
            if (typeof context.diagramChanges !== 'string' || context.diagramChanges.trim().length === 0) {
                throw new Error('Cannot resolve diagram-changes placeholder without reviewed diagram changes');
            }

            return context.diagramChanges;
        }
        if (name === 'diagram-file') {
            if (context.kind !== 'diagram') throw new Error('Cannot resolve diagram-file placeholder outside diagram context');
            if (typeof diagramFile !== 'string' || diagramFile.length === 0) {
                throw new Error('Cannot resolve diagram-file placeholder without a diagram output path');
            }

            return diagramFile;
        }
        if (name === 'parent-node') {
            if (context.kind !== 'diagram' || context.type !== 'child') {
                throw new Error('Cannot resolve parent-node placeholder outside child diagram context');
            }
            if (!context.parentNode) {
                throw new Error('Cannot resolve parent-node placeholder without a selected diagram item label');
            }

            return context.parentNode;
        }
        if (name === 'conflict-file') {
            if (!context.conflictFile) throw new Error('Cannot resolve conflict-file placeholder without a selected conflict file');

            return context.conflictFile;
        }
        if (name === 'conflict-files') {
            if (!context.conflictFiles) throw new Error('Cannot resolve conflict-files placeholder without conflict files');

            return context.conflictFiles;
        }
        if (name === 'card-title') {
            if (!context.title) throw new Error('Cannot resolve card-title placeholder without a card title');

            return context.title;
        }
        if (!context.file) throw new Error(`Cannot resolve ${name} placeholder without a file context`);

        return context.file;
    });
}

function composeAgentPrompt(prompt, output, diagramFooter) {
    if (output?.kind !== 'diagram') return prompt;
    if (typeof diagramFooter !== 'string' || diagramFooter.length === 0) throw new Error('Missing diagram footer');

    return `${prompt}\n\n${diagramFooter}`;
}

function resolveAgentPrompt(
    action,
    context,
    runProject,
    primaryProject,
    projectFolder,
    releasesFolder,
    activeCardsFolder,
    extraPrompt,
    diagramFooter,
    diagramFile,
    version,
) {
    const composedPrompt = composeAgentPrompt(action.prompt, action.output, diagramFooter);
    const prompt = resolvePlaceholders(
        composedPrompt,
        context,
        runProject,
        primaryProject,
        projectFolder,
        releasesFolder,
        activeCardsFolder,
        extraPrompt,
        diagramFile,
        version,
    );
    if (CARD_PROMPT_PLACEHOLDER_PATTERN.test(action.prompt) || extraPrompt.trim().length === 0) return prompt;

    return `${prompt}\n\n${extraPrompt}`;
}

/** Resolves recognized placeholders entered in the editable agent popup prompt. */
function resolvePopupPrompt(
    text, context, runProject, primaryProject, projectFolder, releasesFolder, activeCardsFolder, diagramFile, version,
) {
    return resolvePlaceholders(
        text,
        context,
        runProject,
        primaryProject,
        projectFolder,
        releasesFolder,
        activeCardsFolder,
        '',
        diagramFile,
        version,
    );
}

module.exports = { composeAgentPrompt, resolveAgentPrompt, resolvePlaceholders, resolvePopupPrompt };

